export default function Steps(){

const steps=[
"Enter Email",
"Magic link generated",
"Email sent",
"Click & login"
]

return(

<section id="steps" className="py-24 px-10">

<h2 className="text-4xl text-center font-bold text-gradient mb-16">
How It Works
</h2>

<div className="grid md:grid-cols-4 gap-6">

{steps.map((s,i)=>(
<div key={i} className="glass-card card-hover p-6 text-center">

<h3 className="text-2xl mb-3">{i+1}</h3>

<p>{s}</p>

</div>
))}

</div>

</section>

)

}
